<template><article><NuxtLink to="/docs" class="text-sm">← All guides</NuxtLink><p class="doc-label mt-5">Secure V2 · SDK 0.3.0</p><h1 class="doc-title">{{guide.title}}</h1><p class="doc-updated">Updated October 11, 2026 · verified against repository implementation</p><p class="doc-lede">{{guide.summary}}</p><nav aria-label="On this page" class="card mt-5 p-4"><a v-for="(section,i) in guide.sections" :key="section.title" :href="'#step-'+i" class="mb-2 block text-sm">{{section.title}}</a></nav><section v-for="(section,i) in guide.sections" :id="'step-'+i" :key="section.title" class="scroll-mt-20"><h2>{{section.title}}</h2><p v-for="paragraph in section.paragraphs" :key="paragraph">{{paragraph}}</p><DocCode v-if="section.code" :code="section.code"/></section><nav class="mt-8 grid gap-2 sm:grid-cols-2" aria-label="Related guides"><NuxtLink v-for="other in related" :key="other.slug" :to="'/docs/'+other.slug">{{other.title}}</NuxtLink></nav><p class="mt-6"><NuxtLink to="/dashboard/schema">Open device setup</NuxtLink> · <a href="mailto:support@usestruct.com">Contact support</a></p></article></template>
<script setup lang="ts">import {GUIDES,guideBySlug} from '#shared/documentation';definePageMeta({layout:'doc'});const route=useRoute();const guide=computed(()=>{const value=guideBySlug(String(route.params.slug));if(!value)throw createError({statusCode:404,statusMessage:'Guide not found'});return value});const related=computed(()=>GUIDES.filter(g=>g.slug!==guide.value.slug&&g.slug!=='compatibility'));useSeoMeta({title:()=>guide.value.title+' — Struct Docs'})</script>
